  if (has_parameter_is_tupled_arguments_) AppendJsonField("parameter_is_tupled_arguments", parameter_is_tupled_arguments_, &first, &out);
  if (has_executable_build_options_) AppendJsonField("executable_build_options", executable_build_options_, &first, &out);
  if (has_compile_portable_executable_) AppendJsonField("compile_portable_executable", compile_portable_executable_, &first, &out);
  if (has_profile_version_) AppendJsonField("profile_version", profile_version_, &first, &out);
  if (has_serialized_multi_slice_config_) AppendJsonField("serialized_multi_slice_config", serialized_multi_slice_config_, &first, &out);
  if (!env_options_.empty()) AppendJsonRepeatedField("env_options", env_options_, &first, &out);
  out += "}";
